html:
{%- set doc = doc -%}
<style>
  body { font-family: Arial, sans-serif; font-size: 12px; color: #333; }
  .title { text-align:right; font-size:22px; color:#888; letter-spacing:2px; text-transform:uppercase; }
  .slip-id { text-align:right; font-size:12px; color:#555; margin-bottom:20px; }
  table { width:100%; border-collapse:collapse; margin:16px 0; }
  thead tr { background:#f0f0f0; }
  th, td { border:1px solid #ccc; padding:6px 8px; }
  td.num { text-align:right; }
  .pkg { display:inline-block; background:#e8f0fe; color:#1a56db; 
         border-radius:3px; padding:1px 6px; font-size:11px; margin:2px 0; }
</style>

<div class="title">Packing Slip</div>
<div class="slip-id">{{ doc.name }}</div>
<hr>

<table style="border:none; margin: 0; padding: 0;">
  <tr style="border:none;">
    <td style="border:none; padding-left:0;"><b>Delivery Note:</b> {{ doc.delivery_note or '' }}</td>
  </tr>

</table>

<table>
  <thead>
    <tr>
      <th>Sr</th>
      <th>Item Code</th>
      <th>Item Name</th>
      <th>Quantity</th>
      <th>Net Weight</th>
      <th>UOM</th>
      <th>Package No. (Qty per Package)</th>
    </tr>
  </thead>
  <tbody>
    {% for item in doc.items %}
    <tr>
      <td>{{ loop.index }}</td>
      <td>{{ item.item_code }}</td>
      <td>{{ item.item_name }}</td>
      <td class="num">{{ item.qty }}</td>
      <td class="num">{{ item.net_weight }}</td>
      <td>{{ item.stock_uom or item.uom or '' }}</td>
      <td>
        {% if item.package_no %}
          {% for line in item.package_no.split('\n') %}
            {% if line.strip() %}
              <div class="pkg">{{ line.strip() }}</div>
            {% endif %}
          {% endfor %}
        {% endif %}
      </td>
    </tr>
    {% endfor %}
  </tbody>
</table>

<table style="border:none; margin: 10px 0;">
  <tr style="border:none;">
    <td style="border:none; padding-left:0;"><b>Net Weight:</b> {{ doc.net_weight_pkg }}</td>
    <td style="border:none; text-align:right; padding-right:0;"><b>Gross Weight:</b> {{ doc.gross_weight_pkg }}</td>
  </tr>
</table>
